#!/bin/bash
# ==============================================================================
# Allwinner A733 SD Card Universal Fix Script (v2.5 - Hardware Reference Parity)
# Supports: Orange Pi 4 Pro, Radxa Cubie A7A, Radxa Cubie A7S, Banana Pi M8
# ==============================================================================
set -euo pipefail

if [ "$(id -u)" -ne 0 ]; then
  echo "[-] Error: Must be run as root"
  exit 1
fi

TARGET="${1:-}"
BOARD="${2:-auto}"

if [ -z "$TARGET" ]; then
  echo "Usage: sudo $0 <sdcard_block_device_or_mountpoint> [opi4pro|cubie-a7a|cubie-a7s|bananapi-m8]"
  echo "Examples:"
  echo "  sudo $0 /dev/mmcblk0"
  echo "  sudo $0 /dev/sdb cubie-a7a"
  echo "  sudo $0 /media/jonas/opi_root"
  exit 1
fi

CLEANUP_MOUNT=0
MNT=""
RAW_DEV=""

if [ -b "$TARGET" ]; then
  if [[ "$TARGET" =~ [0-9]p[0-9]+$ ]] || [[ "$TARGET" =~ /dev/sd[a-z]+[0-9]+$ ]] || [[ "$TARGET" =~ /dev/vd[a-z]+[0-9]+$ ]] || [[ "$TARGET" =~ /dev/nvme[0-9]+n[0-9]+p[0-9]+$ ]] || [[ "$TARGET" =~ /dev/mmcblk[0-9]+p[0-9]+$ ]] || [[ "$TARGET" =~ /dev/loop[0-9]+p[0-9]+$ ]]; then
    PART="$TARGET"
    RAW_DEV="${TARGET%p[0-9]*}"
    [[ "$RAW_DEV" == "$TARGET" ]] && RAW_DEV="${TARGET%[0-9]*}"
  else
    RAW_DEV="$TARGET"
    PART="${TARGET}p1"
    [ -b "$PART" ] || PART="${TARGET}1"
    if [ ! -b "$PART" ]; then
      echo "[-] Could not find partition 1 on $TARGET"
      exit 1
    fi
  fi
  if grep -qs "^$PART " /proc/mounts; then
    umount -l "$PART" || true
  fi
  MNT="/mnt/a733_fix_$$"
  mkdir -p "$MNT"
  CLEANUP_MOUNT=1
  echo "[*] Mounting $PART -> $MNT..."
  mount "$PART" "$MNT"
elif [ -d "$TARGET" ]; then
  if [ -d "$TARGET/boot" ]; then
    MNT="$TARGET"
  elif [ -f "$TARGET/uImage" ] || [ -f "$TARGET/vmlinux-6.18.63-sun60iw2" ]; then
    MNT="$(dirname "$TARGET")"
  else
    MNT="$TARGET"
  fi
else
  echo "[-] Target $TARGET is neither a block device nor a directory"
  exit 1
fi

cleanup() {
  if [ "$CLEANUP_MOUNT" -eq 1 ] && [ -n "$MNT" ]; then
    sync || true
    umount -l "$MNT" 2>/dev/null || true
    rmdir "$MNT" 2>/dev/null || true
  fi
  rm -rf "/tmp/a733_fix_payload_$$" 2>/dev/null || true
}
trap cleanup EXIT INT TERM

if [ ! -d "$MNT/boot" ]; then
  echo "[-] Error: Target does not have a /boot directory at $MNT/boot"
  exit 1
fi

if [ "$BOARD" = "auto" ]; then
  if [ -f "$MNT/etc/hostname" ]; then
    HNAME="$(cat "$MNT/etc/hostname" | tr -d " \r\n")"
    if [[ "$HNAME" == *"cubie-a7a"* ]]; then
      BOARD="cubie-a7a"
    elif [[ "$HNAME" == *"cubie-a7s"* ]]; then
      BOARD="cubie-a7s"
    elif [[ "$HNAME" == *"bananapi"* ]] || [[ "$HNAME" == *"bpi-m8"* ]]; then
      BOARD="bananapi-m8"
    elif [[ "$HNAME" == *"orangepi"* ]]; then
      BOARD="opi4pro"
    fi
  fi
fi

if [ "$BOARD" = "auto" ]; then
  if [ -f "$MNT/boot/bananapiEnv.txt" ]; then
    BOARD="bananapi-m8"
  elif [ -f "$MNT/boot/radxaEnv.txt" ]; then
    if grep -q "cubie-a7s" "$MNT/boot/radxaEnv.txt" 2>/dev/null; then
      BOARD="cubie-a7s"
    else
      BOARD="cubie-a7a"
    fi
  elif [ -f "$MNT/boot/orangepiEnv.txt" ]; then
    if grep -q "cubie-a7a" "$MNT/boot/orangepiEnv.txt" 2>/dev/null; then
      BOARD="cubie-a7a"
    elif grep -q "cubie-a7s" "$MNT/boot/orangepiEnv.txt" 2>/dev/null; then
      BOARD="cubie-a7s"
    elif grep -q "bananapi" "$MNT/boot/orangepiEnv.txt" 2>/dev/null; then
      BOARD="bananapi-m8"
    else
      BOARD="opi4pro"
    fi
  else
    BOARD="opi4pro"
  fi
fi

echo "[*] Target board identified as: $BOARD"

TMP_PAYLOAD="/tmp/a733_fix_payload_$$"
mkdir -p "$TMP_PAYLOAD"
echo "[*] Unpacking fix assets..."
sed -n '/^__PAYLOAD_START__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xz -C "$TMP_PAYLOAD"

if [ -n "$RAW_DEV" ]; then
  BOOTLOADER_BIN="$TMP_PAYLOAD/bootloader-orangepi-4-pro.bin"
  if [[ "$BOARD" == *"cubie"* ]] && [ -f "$TMP_PAYLOAD/bootloader-radxa-cubie.bin" ]; then
    BOOTLOADER_BIN="$TMP_PAYLOAD/bootloader-radxa-cubie.bin"
    echo "[*] Flashing Radxa vendor-embedded bootloader to $RAW_DEV..."
  elif [ "$BOARD" = "bananapi-m8" ] && [ -f "$TMP_PAYLOAD/bootloader-bananapi-m8.bin" ]; then
    BOOTLOADER_BIN="$TMP_PAYLOAD/bootloader-bananapi-m8.bin"
    echo "[*] Flashing Banana Pi vendor-embedded bootloader to $RAW_DEV..."
  else
    echo "[*] Flashing Orange Pi bootloader (18,178,048 bytes) to $RAW_DEV..."
  fi
  dd if="$BOOTLOADER_BIN" of="$RAW_DEV" bs=512 seek=16 conv=notrunc status=none
fi

KVER="6.18.63-sun60iw2"
for d in "$MNT"/lib/modules/6.*; do
  if [ -d "$d" ]; then
    KVER="$(basename "$d")"
    break
  fi
done
echo "[*] Kernel version in rootfs: $KVER"

if [ "$BOARD" = "bananapi-m8" ]; then
  DTB_NAME="sun60i-a733-bananapi-m8.dtb"
  SPLASH_FILE="$TMP_PAYLOAD/logo.bmp-bananapi"
elif [ "$BOARD" = "opi4pro" ]; then
  DTB_NAME="sun60i-a733-orangepi-4-pro.dtb"
  SPLASH_FILE="$TMP_PAYLOAD/logo.bmp-orangepi"
elif [ "$BOARD" = "cubie-a7s" ]; then
  DTB_NAME="sun60i-a733-cubie-a7s.dtb"
  SPLASH_FILE="$TMP_PAYLOAD/logo.bmp-radxa"
else
  DTB_NAME="sun60i-a733-cubie-a7a.dtb"
  SPLASH_FILE="$TMP_PAYLOAD/logo.bmp-radxa"
fi

echo "[*] Restoring board DTB ($DTB_NAME)..."
mkdir -p "$MNT/boot/dtb/allwinner"
cp -f "$TMP_PAYLOAD/$DTB_NAME" "$MNT/boot/$DTB_NAME"
cp -f "$TMP_PAYLOAD/$DTB_NAME" "$MNT/boot/dtb/allwinner/$DTB_NAME"
cp -f "$TMP_PAYLOAD/sun60i-a733-orangepi-4-pro.dtb" "$MNT/boot/sun60i-a733-orangepi-4-pro.dtb"
cp -f "$TMP_PAYLOAD/sun60i-a733-cubie-a7a.dtb" "$MNT/boot/sun60i-a733-cubie-a7a.dtb"
cp -f "$TMP_PAYLOAD/sun60i-a733-cubie-a7s.dtb" "$MNT/boot/sun60i-a733-cubie-a7s.dtb"
[ -f "$TMP_PAYLOAD/sun60i-a733-bananapi-m8.dtb" ] && cp -f "$TMP_PAYLOAD/sun60i-a733-bananapi-m8.dtb" "$MNT/boot/sun60i-a733-bananapi-m8.dtb"

if [ -d "$MNT/boot/dtb-$KVER/allwinner" ]; then
  cp -f "$TMP_PAYLOAD/sun60i-a733-orangepi-4-pro.dtb" "$MNT/boot/dtb-$KVER/allwinner/"
  cp -f "$TMP_PAYLOAD/sun60i-a733-cubie-a7a.dtb" "$MNT/boot/dtb-$KVER/allwinner/"
  cp -f "$TMP_PAYLOAD/sun60i-a733-cubie-a7s.dtb" "$MNT/boot/dtb-$KVER/allwinner/"
  [ -f "$TMP_PAYLOAD/sun60i-a733-bananapi-m8.dtb" ] && cp -f "$TMP_PAYLOAD/sun60i-a733-bananapi-m8.dtb" "$MNT/boot/dtb-$KVER/allwinner/"
fi

repack_initrd() {
  local splash_blob="$1"
  [ -f "$MNT/boot/uInitrd" ] || return 0
  echo "[*] Injecting authentic vendor bootsplash blob into uInitrd..."
  local tmp_initrd="/tmp/repack_initrd_$$"
  rm -rf "$tmp_initrd"
  mkdir -p "$tmp_initrd"
  dd if="$MNT/boot/uInitrd" bs=64 skip=1 of="$tmp_initrd/initrd.gz" status=none
  (cd "$tmp_initrd" && gzip -dc initrd.gz | cpio -id -m 2>/dev/null)
  cp -f "$splash_blob" "$tmp_initrd/lib/firmware/bootsplash.orangepi"
  [ -d "$tmp_initrd/usr/lib/firmware" ] && cp -f "$splash_blob" "$tmp_initrd/usr/lib/firmware/bootsplash.orangepi"
  (cd "$tmp_initrd" && rm -f initrd.gz && find . | cpio -H newc -o 2>/dev/null | gzip -1 > "$tmp_initrd/new_initrd.gz")
  mkimage -A arm64 -O linux -T ramdisk -C gzip -d "$tmp_initrd/new_initrd.gz" "$MNT/boot/uInitrd" >/dev/null
  rm -rf "$tmp_initrd"
  echo "[✓] Successfully updated uInitrd with vendor bootsplash!"
}

echo "[*] Restoring splash screen boot.bmp and logo.bmp..."
cp -f "$SPLASH_FILE" "$MNT/boot/boot.bmp"
if [ "$BOARD" = "bananapi-m8" ]; then
  [ -f "$TMP_PAYLOAD/logo.bmp-bananapi" ] && cp -f "$TMP_PAYLOAD/logo.bmp-bananapi" "$MNT/boot/logo.bmp"
  if [ -f "$TMP_PAYLOAD/bootsplash.bananapi" ]; then
    echo "[*] Installing Banana Pi kernel bootsplash firmware blob..."
    mkdir -p "$MNT/usr/lib/firmware" "$MNT/lib/firmware"
    cp -f "$TMP_PAYLOAD/bootsplash.bananapi" "$MNT/lib/firmware/bootsplash.bananapi"
    cp -f "$TMP_PAYLOAD/bootsplash.bananapi" "$MNT/usr/lib/firmware/bootsplash.bananapi"
    cp -f "$TMP_PAYLOAD/bootsplash.bananapi" "$MNT/lib/firmware/bootsplash.orangepi"
    cp -f "$TMP_PAYLOAD/bootsplash.bananapi" "$MNT/usr/lib/firmware/bootsplash.orangepi"
    repack_initrd "$TMP_PAYLOAD/bootsplash.bananapi"
  fi
elif [[ "$BOARD" == *"cubie"* ]]; then
  [ -f "$TMP_PAYLOAD/logo.bmp-radxa" ] && cp -f "$TMP_PAYLOAD/logo.bmp-radxa" "$MNT/boot/logo.bmp"
  if [ -f "$TMP_PAYLOAD/bootsplash.radxa" ]; then
    echo "[*] Installing Radxa kernel bootsplash firmware blob..."
    mkdir -p "$MNT/usr/lib/firmware" "$MNT/lib/firmware"
    cp -f "$TMP_PAYLOAD/bootsplash.radxa" "$MNT/lib/firmware/bootsplash.radxa"
    cp -f "$TMP_PAYLOAD/bootsplash.radxa" "$MNT/usr/lib/firmware/bootsplash.radxa"
    cp -f "$TMP_PAYLOAD/bootsplash.radxa" "$MNT/lib/firmware/bootsplash.orangepi"
    cp -f "$TMP_PAYLOAD/bootsplash.radxa" "$MNT/usr/lib/firmware/bootsplash.orangepi"
    repack_initrd "$TMP_PAYLOAD/bootsplash.radxa"
  fi
elif [ "$BOARD" = "opi4pro" ]; then
  [ -f "$TMP_PAYLOAD/logo.bmp-orangepi" ] && cp -f "$TMP_PAYLOAD/logo.bmp-orangepi" "$MNT/boot/logo.bmp"
  if [ -f "$TMP_PAYLOAD/bootsplash.orangepi" ]; then
    echo "[*] Installing Orange Pi kernel bootsplash firmware blob..."
    mkdir -p "$MNT/usr/lib/firmware" "$MNT/lib/firmware"
    cp -f "$TMP_PAYLOAD/bootsplash.orangepi" "$MNT/lib/firmware/bootsplash.orangepi"
    cp -f "$TMP_PAYLOAD/bootsplash.orangepi" "$MNT/usr/lib/firmware/bootsplash.orangepi"
    repack_initrd "$TMP_PAYLOAD/bootsplash.orangepi"
  fi
fi

# Ensure bootsplash unblanks cleanly before getty starts
cat << 'BS_EOF' > "$MNT/usr/lib/systemd/system/bootsplash-hide-when-booted.service"
[Unit]
Description=Hide bootsplash after starting the system
DefaultDependencies=no
After=basic.target
Before=getty.target
ConditionPathExists=/sys/devices/platform/bootsplash.0/enabled

[Service]
Type=oneshot
ExecStart=/bin/sh -c 'echo off > /sys/devices/platform/bootsplash.0/enabled'
RemainAfterExit=yes

[Install]
WantedBy=basic.target multi-user.target getty.target
BS_EOF
[ -f "$MNT/lib/systemd/system/bootsplash-hide-when-booted.service" ] && [ "$MNT/usr/lib" != "$MNT/lib" ] && cp -f "$MNT/usr/lib/systemd/system/bootsplash-hide-when-booted.service" "$MNT/lib/systemd/system/bootsplash-hide-when-booted.service" 2>/dev/null || true
mkdir -p "$MNT/etc/systemd/system/basic.target.wants" "$MNT/etc/systemd/system/multi-user.target.wants" "$MNT/etc/systemd/system/getty.target.wants"
ln -sf /usr/lib/systemd/system/bootsplash-hide-when-booted.service "$MNT/etc/systemd/system/basic.target.wants/" 2>/dev/null || true
ln -sf /usr/lib/systemd/system/bootsplash-hide-when-booted.service "$MNT/etc/systemd/system/multi-user.target.wants/" 2>/dev/null || true
ln -sf /usr/lib/systemd/system/bootsplash-hide-when-booted.service "$MNT/etc/systemd/system/getty.target.wants/" 2>/dev/null || true
ln -sf /usr/lib/systemd/system/multi-user.target "$MNT/etc/systemd/system/default.target"
rm -f "$MNT/etc/systemd/system/serial-getty@'ttyS0'.service" "$MNT/etc/systemd/system/serial-getty@\"ttyS0\".service" 2>/dev/null || true
rm -f "$MNT/root/.not_logged_in_yet"
echo "[*] Restoring verified standard reference boot.cmd & boot.scr..."
cp -f "$TMP_PAYLOAD/ref_boot.cmd" "$MNT/boot/boot.cmd"
cp -f "$TMP_PAYLOAD/ref_boot.scr" "$MNT/boot/boot.scr"
cp -f "$TMP_PAYLOAD/toggle-a733-logging.sh" "$MNT/boot/toggle-a733-logging.sh"
chmod +x "$MNT/boot/toggle-a733-logging.sh"
[ -d "$MNT/usr/local/bin" ] && cp -f "$TMP_PAYLOAD/toggle-a733-logging.sh" "$MNT/usr/local/bin/toggle-a733-logging" && chmod +x "$MNT/usr/local/bin/toggle-a733-logging"

echo "[*] Restoring standard boot environment (both HDMI display and UART serial console active)..."
cat << ENV_EOF > "$MNT/boot/orangepiEnv.txt"
verbosity=7
bootlogo=false
console=both
earlycon=on
overlay_prefix=sun60i-a733
fdtfile=allwinner/$DTB_NAME
rootdev=/dev/mmcblk0p1
rootfstype=ext4
extraargs=cma=256M
ENV_EOF

# Provide compatibility copies so any script reading radxaEnv / bananapiEnv gets the exact matching config
cp -f "$MNT/boot/orangepiEnv.txt" "$MNT/boot/radxaEnv.txt"
cp -f "$MNT/boot/orangepiEnv.txt" "$MNT/boot/bananapiEnv.txt"
cp -f "$MNT/boot/orangepiEnv.txt" "$MNT/boot/a733-allwinnerEnv.txt"

echo "[*] Installing Maxio PHY Ethernet driver module (maxio.ko)..."
NET_DIR="$MNT/lib/modules/$KVER/kernel/drivers/net/phy"
if [ -d "$NET_DIR" ]; then
  cp -f "$TMP_PAYLOAD/maxio.ko" "$NET_DIR/"
fi

echo "[*] Installing AIC8800 Wi-Fi & Bluetooth driver modules and firmware..."
WIFI_DIR="$MNT/lib/modules/$KVER/kernel/drivers/net/wireless/aic8800"
mkdir -p "$WIFI_DIR"
cp -f "$TMP_PAYLOAD/aic8800_bsp.ko" "$WIFI_DIR/"
cp -f "$TMP_PAYLOAD/aic8800_fdrv.ko" "$WIFI_DIR/"
cp -f "$TMP_PAYLOAD/aic8800_btlpm.ko" "$WIFI_DIR/"

FW_DIR="$MNT/lib/firmware/aic8800D80"
mkdir -p "$FW_DIR"
ln -sfn aic8800D80 "$MNT/lib/firmware/aic8800_fw"
ln -sfn aic8800D80 "$MNT/lib/firmware/aic8800d80"

echo "[*] Installing SocketCAN driver modules (can.ko, can-raw.ko, can-dev.ko, gs_usb.ko)..."
CAN_DIR="$MNT/lib/modules/$KVER/kernel/net/can"
CAN_DEV_DIR="$MNT/lib/modules/$KVER/kernel/drivers/net/can"
CAN_USB_DIR="$MNT/lib/modules/$KVER/kernel/drivers/net/can/usb"
mkdir -p "$CAN_DIR" "$CAN_DEV_DIR" "$CAN_USB_DIR"
[ -f "$TMP_PAYLOAD/can.ko" ] && cp -f "$TMP_PAYLOAD/can.ko" "$CAN_DIR/"
[ -f "$TMP_PAYLOAD/can-raw.ko" ] && cp -f "$TMP_PAYLOAD/can-raw.ko" "$CAN_DIR/"
[ -f "$TMP_PAYLOAD/can-dev.ko" ] && cp -f "$TMP_PAYLOAD/can-dev.ko" "$CAN_DEV_DIR/"
[ -f "$TMP_PAYLOAD/gs_usb.ko" ] && cp -f "$TMP_PAYLOAD/gs_usb.ko" "$CAN_USB_DIR/"

cat << MODS_EOF > "$MNT/etc/modules-load.d/a733-hardware.conf"
maxio
aic8800_bsp
aic8800_fdrv
can
can_raw
can_dev
gs_usb
MODS_EOF

echo "[*] Running depmod for $KVER..."
depmod -a -b "$MNT" "$KVER" 2>/dev/null || true

echo "[*] Installing a733-config utility..."
if [ -d "$TMP_PAYLOAD/a733-config" ]; then
  cp -rf "$TMP_PAYLOAD/a733-config/usr/"* "$MNT/usr/" 2>/dev/null || true
  ln -sf orangepi-config "$MNT/usr/sbin/a733-config" 2>/dev/null || true
  ln -sf orangepi-config "$MNT/usr/bin/a733-config" 2>/dev/null || true
fi

MOTD_CFG="$MNT/etc/update-motd.d/41-orangepi-config"
if [ -f "$MOTD_CFG" ]; then
  cat << 'CFG_EOF' > "$MOTD_CFG"
#!/bin/bash
THIS_SCRIPT="config"
MOTD_DISABLE=""
[[ -f /etc/default/orangepi-motd ]] && . /etc/default/orangepi-motd
for f in $MOTD_DISABLE; do [[ $f == $THIS_SCRIPT ]] && exit 0; done

if [[ -f /usr/sbin/a733-config ]] || [[ -f /usr/sbin/orangepi-config ]]; then
  echo -e "[\e[32m System Configuration Utility\e[0m: \e[1ma733-config\e[0m (or \e[1msudo a733-config\e[0m) ]\n"
fi
exit 0
CFG_EOF
  chmod +x "$MOTD_CFG"
fi

echo "[*] Ensuring SSH standalone service is enabled with automatic host-key generation..."
mkdir -p "$MNT/etc/systemd/system/multi-user.target.wants"
rm -rf "$MNT/etc/systemd/system/ssh.service.requires" 2>/dev/null || true
rm -f "$MNT/etc/systemd/system/sockets.target.wants/ssh.socket" 2>/dev/null || true
rm -f "$MNT/etc/systemd/system/ssh.socket" 2>/dev/null || true
for s in "$MNT/usr/lib/systemd/system/ssh.service" "$MNT/lib/systemd/system/ssh.service"; do
  if [ -f "$s" ]; then
    ln -sf "${s#$MNT}" "$MNT/etc/systemd/system/multi-user.target.wants/ssh.service"
    ln -sf ssh.service "$MNT/etc/systemd/system/sshd.service"
    break
  fi
done

# Ensure pre-generated ssh host keys exist right now
mkdir -p "$MNT/etc/ssh"
ssh-keygen -A -f "$MNT" 2>/dev/null || true

# Add systemd drop-in override so sshd ALWAYS generates missing keys before starting
mkdir -p "$MNT/etc/systemd/system/ssh.service.d"
cat << SSH_OVERRIDE_EOF > "$MNT/etc/systemd/system/ssh.service.d/override.conf"
[Service]
ExecStartPre=-/usr/bin/ssh-keygen -A
SSH_OVERRIDE_EOF

echo "[*] Updating systemd service names (orangepi-* -> a733-allwinner-*)..."
SYS_UNITS="$MNT/usr/lib/systemd/system"
[ -d "$SYS_UNITS" ] || SYS_UNITS="$MNT/lib/systemd/system"
if [ -d "$SYS_UNITS" ]; then
  for u in "$SYS_UNITS"/orangepi-*.service; do
    if [ -f "$u" ] && [ ! -L "$u" ]; then
      u_base="$(basename "$u")"
      new_base="${u_base/orangepi-/a733-allwinner-}"
      cp -f "$u" "$SYS_UNITS/$new_base"
      rm -f "$u"
      ln -sf "$new_base" "$u"
    fi
  done
fi

echo "[+] Applying board branding (Banana Pi OS / Radxa OS / Orange Pi, MOTD, ASCII art)..."
if [ "$BOARD" = "bananapi-m8" ]; then
  if [ -f "$TMP_PAYLOAD/update-bananapi-branding.sh" ]; then
    bash "$TMP_PAYLOAD/update-bananapi-branding.sh" "$MNT" "$BOARD"
  fi
elif [ -f "$TMP_PAYLOAD/update-radxa-branding.sh" ]; then
  bash "$TMP_PAYLOAD/update-radxa-branding.sh" "$MNT" "$BOARD"
fi

# Clean foreign user accounts - only keep the board manufacturer account
echo "[*] Ensuring clean single user account for board: $BOARD..."
KEEP_USER="orangepi"
if [ "$BOARD" = "bananapi-m8" ]; then
  KEEP_USER="bananapi"
elif [[ "$BOARD" == *"cubie"* ]]; then
  KEEP_USER="radxa"
fi

for u in orangepi radxa bananapi; do
  if [ "$u" != "$KEEP_USER" ]; then
    if grep -q "^$u:" "$MNT/etc/passwd"; then
      echo "[-] Removing non-board user ..."
      sed -i "/^$u:/d" "$MNT/etc/passwd" "$MNT/etc/shadow" "$MNT/etc/group" 2>/dev/null || true
      rm -rf "$MNT/home/$u" 2>/dev/null || true
      rm -f "$MNT/etc/sudoers.d/010_$u-nopasswd" 2>/dev/null || true
    fi
  fi
done

echo "[+] Configuring serial & display autologin..."
if [ "$BOARD" = "bananapi-m8" ]; then
  LOGIN_USER="bananapi"
elif [ "$BOARD" = "opi4pro" ]; then
  LOGIN_USER="orangepi"
else
  LOGIN_USER="radxa"
fi
mkdir -p "$MNT/etc/systemd/system/getty.target.wants"
ln -sf /usr/lib/systemd/system/serial-getty@.service "$MNT/etc/systemd/system/getty.target.wants/serial-getty@ttyS0.service"
ln -sf /usr/lib/systemd/system/getty@.service "$MNT/etc/systemd/system/getty.target.wants/getty@tty1.service"

mkdir -p "$MNT/etc/systemd/system/serial-getty@ttyS0.service.d"
cat << 'SGETTY_EOF' > "$MNT/etc/systemd/system/serial-getty@ttyS0.service.d/override.conf"
[Service]
ExecStart=
ExecStart=-/sbin/agetty -o '-p -f -- \u' --keep-baud --autologin $LOGIN_USER 115200,38400,9600 %I dumb
SGETTY_EOF

mkdir -p "$MNT/etc/systemd/system/getty@tty1.service.d"
cat << 'TTY1_EOF' > "$MNT/etc/systemd/system/getty@tty1.service.d/override.conf"
[Service]
ExecStart=
ExecStartPre=-/bin/sh -c 'test -e /sys/devices/platform/bootsplash.0/enabled && echo off > /sys/devices/platform/bootsplash.0/enabled || true'
ExecStart=-/sbin/agetty -o '-p -f -- \u' --noclear --autologin $LOGIN_USER %I linux
TTY1_EOF

sync
echo "======================================================================"
echo "[✓] SUCCESS: All fixes applied to SD card!"
echo "    - Board: $BOARD (DTB: $DTB_NAME)"
echo "    - Universal sector 16 bootloader active (18,178,048 bytes)"
